<?php

namespace App\Http\Middleware;

use App\Models\SocialStudioSettings;
use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

/**
 * Guards the reel render API that the GitHub Actions render job calls. The
 * token is generated by the site and stored as the SOCIAL_RENDER_TOKEN Actions
 * secret. Timing-safe, and fails shut when no token has been made yet.
 */
class VerifySocialRenderToken
{
    public function handle(Request $request, Closure $next): Response
    {
        $expected = SocialStudioSettings::instance()->render_token;

        if (empty($expected)) {
            return response()->json(['message' => 'Render API is not configured.'], 503);
        }

        $provided = $request->bearerToken();

        if (! is_string($provided) || ! hash_equals($expected, $provided)) {
            return response()->json(['message' => 'Invalid or missing render token.'], 401);
        }

        return $next($request);
    }
}
